/**
 * Types and helpers for ARKStatsExtractor-derived species data
 * (data/ase-species.json, generated by scripts/extract-ase-species.ts).
 *
 * Conventions match ASE (github.com/cadon/ARKStatsExtractor) and the
 * ark-stat-calculation skill: 12 stats in ASE index order, per-stat raw values
 * [B, Iw, Id, Ta, Tm] where Iw/Id are fractions, Ta is absolute, Tm is a
 * TE-scaled fraction (negatives already clamped to 0 in the data).
 */

export const STATS_COUNT = 12

/** ini-key for each ASE stat index 0–11. */
export const ASE_STAT_KEYS = [
  'health',
  'stamina',
  'torpidity',
  'oxygen',
  'food',
  'water',
  'temperature',
  'weight',
  'meleeDamage',
  'movementSpeed',
  'fortitude',
  'craftingSkill',
] as const

export type AseStatKey = (typeof ASE_STAT_KEYS)[number]

export const HEALTH = 0
export const TORPIDITY = 2
export const SPEED = 9

/**
 * ASE per-species default imprint multipliers, by stat index. The 0.2 imprint
 * scale lives here — Stamina, Oxygen, Temperature, Fortitude and Crafting never
 * receive an imprint bonus; everything else (incl. Torpidity and Food) does.
 */
export const DEFAULT_IMPRINT_MULT = [0.2, 0, 0.2, 0, 0.2, 0.2, 0, 0.2, 0.2, 0.2, 0, 0] as const

/**
 * Per-stat server multipliers [TaM, TmM, IdM, IwM] applied to the raw species
 * values: additive taming bonus, multiplicative taming bonus, per-dom-level and
 * per-wild-level increase. These are the game's official defaults (ARKStatsExtractor
 * `serverMultipliers.json` → "official"); only Health and Melee differ from 1.
 * Without them Health and Melee can't be solved (e.g. Health Ta 0.5 is really +0.07).
 */
export type StatMultipliers = [taM: number, tmM: number, idM: number, iwM: number]
export const OFFICIAL_STAT_MULTIPLIERS: (StatMultipliers | null)[] = [
  [0.14, 0.44, 0.2, 1], // Health
  null, null, null, null, null, null, null,
  [0.14, 0.44, 0.17, 1], // Melee Damage
  null, null, null,
]

export type AseSpeciesEntry = {
  name: string
  game: 'ASE' | 'ASA'
  /** Per stat index 0-11: [B, Iw, Id, Ta, Tm], or null when the species doesn't use the stat. */
  stats: ([number, number, number, number, number] | null)[]
  /** TamedBaseHealthMultiplier — Health only, only when tamed/bred. Default 1. */
  tbhm?: number
  /** Per-stat imprint multipliers; default DEFAULT_IMPRINT_MULT. */
  imprintMult?: number[]
  /** Per-stat mutated-level multipliers; default all 1. */
  mutationMult?: number[]
  /** Bitmask of stats that never receive wild levels (ASA: always includes Speed). */
  skipWildLevels?: number
  /** Bitmask of stats displayed in game; dom levels only land in displayed stats. */
  displayedStats?: number
  /** Bitmask of stats whose level-ups are additive (fixed amounts) instead of percentage. */
  levelUpsAdditive?: number
  /** Per stat index (string): hard value cap. */
  statCaps?: Record<string, number>
  /** Per stat index (string): alternative "Troodonism" base value. */
  altBaseStats?: Record<string, number>
  /** Species affected by the flyer speed-leveling restriction. */
  flyer?: boolean
}

export type AseSpeciesFile = {
  generatedFrom: { ase: string; asa: string }
  remaps: Record<string, string>
  species: Record<string, AseSpeciesEntry>
}

/**
 * Normalize an export's DinoClass value to the lookup key used in
 * data/ase-species.json: bare blueprint path, lowercased, no trailing `_C`.
 * Handles decorated forms like `BlueprintGeneratedClass '/Game/...Rex_Character_BP_C'`.
 */
export function normalizeBlueprintPath(dinoClass: string): string {
  let p = dinoClass.trim()
  const slash = p.indexOf('/')
  if (slash > 0) p = p.slice(slash)
  p = p.replace(/['"\s]+$/g, '')
  if (p.endsWith('_C')) p = p.slice(0, -2)
  return p.toLowerCase()
}
